      const dY = 0.35 * dFast.y + 0.65 * dSlow.y;
      const dZ = 0.72 * dFast.z + 0.28 * dSlow.z;

      const ex = ref.x - p.x;
      const ey = ref.y - p.y;
      const ez = ref.z - p.z;

