          }
        }
      }

      const yawRate = clamp(-3.2 * att.yaw - 2.4 * yawInt - 0.15 * rates.yaw, -2, 2);
      lastThrust = thrust;
      lastRoll = roll;
      lastPitch = pitch;

      return { thrust, roll, pitch, yawRate };
