      let maxRefSpeedXZ = 1.55;
      let maxRefSpeedY = 1.10;

      if (phase === 'exit') {
        const g = activeGate;
        target = { x: g.x + 0.34, y: g.y, z: g.z };
        maxRefSpeedXZ = 1.30;
        if (p.x >= g.x + 0.21 && vf.x > -0.05) {
