            !climbHold &&
            ex < 0.12 &&
            ey < 0.072 &&
            ez < 0.048 &&
            Math.abs(vf.x) < 0.25 &&
            Math.abs(vf.y) < 0.18 &&
            Math.abs(vf.z) < 0.15 &&
            gustTransient < 1.4
