      }

      // 4. Smooth ref filter
      const rxErr = target.x - ref.x;
      const ryErr = target.y - ref.y;
      const rzErr = target.z - ref.z;
      const kRef = 4.3;
      let vxDes = rxErr * kRef;
      let vzDes = rzErr * kRef;
